        ("Scenario: How do you handle click events on 50 dynamically added delete buttons in a table?", "Attach a single click listener on the <table> using event delegation with e.target.closest('.btn-delete').", "Intermediate", "Scenario", "table.addEventListener('click', (e) => {\n  const btn = e.target.closest('.btn-delete');\n  if (btn) btn.closest('tr').remove();\n});", "Why is this better than adding 50 listeners?"),
