        ("What does .next() do in jQuery?", ".next() gets the immediately following sibling of each element in the matched set.", "Easy", "Practical", "$('#step1').next().addClass('current');", "What does .nextAll() do?"),
        ("What does .nextAll() do in jQuery?", ".nextAll() gets all siblings following the element in the DOM tree.", "Easy", "Concept", "$('#step2').nextAll().addClass('future');", "What does .nextUntil() do?"),
        ("What does .prev() do in jQuery?", ".prev() gets the immediately preceding sibling of each element in the matched set.", "Easy", "Practical", "$('#step2').prev().addClass('completed');", "What does .prevAll() do?"),
        ("What does .prevAll() do in jQuery?", ".prevAll() gets all siblings preceding the element in the DOM tree.", "Easy", "Concept", "$('#step3').prevAll().addClass('completed');", "What does .prevUntil() do?"),
        ("What does .first() do in jQuery?", ".first() reduces the matched set of elements to only the first one in the set.", "Easy", "Practical", "$('p').first().css('font-size', '20px');", "How does .first() differ from .eq(0)?"),
        ("What does .last() do in jQuery?", ".last() reduces the matched set of elements to only the last one in the set.", "Easy", "Practical", "$('p').last().addClass('footer-note');", "What does .eq(-1) do?"),
        ("What does .filter(selector) do in jQuery?", ".filter(selector) reduces the matched set to only those elements that match the selector or pass a function test.", "Intermediate", "Practical", "$('div').filter('.highlight').show();", "How does .filter differ from .find()?"),
        ("What is the difference between .find() and .filter() in jQuery?", ".find() searches down through DESCENDANTS of the current selection. .filter() tests the CURRENT elements in the selection itself.", "Intermediate", "Comparison", "$('.cards').find('.btn'); // Looks inside .cards\n$('.cards').filter('.active'); // Filters .cards themselves", "Why is this a common beginner confusion?"),
        ("What does .not(selector) do in jQuery?", ".not(selector) removes elements matching the selector from the set of matched elements (opposite of .filter()).", "Easy", "Practical", "$('input').not(':submit').val('');", "Can .not() accept a function?"),
        ("What does .has(selector) do in jQuery?", ".has(selector) reduces the matched set to only those elements that have a descendant matching the selector.", "Intermediate", "Concept", "$('li').has('ul').addClass('has-submenu');", "How does this differ from the CSS :has selector?"),
        ("What does .is(selector) do in jQuery?", ".is(selector) checks the current matched set against a selector/element and returns a boolean (true or false).", "Intermediate", "Practical", "if ($(this).is(':checked')) { ... }", "Does .is() return a jQuery object?"),
        ("What does .slice(start, end) do in jQuery?", ".slice() reduces the matched set of elements to a subset specified by a range of indices.", "Intermediate", "Practical", "$('li').slice(0, 3).addClass('top-three');", "Does slice support negative indices?"),
        ("What does .contents() do in jQuery?", ".contents() gets the children of each element in the matched set, including text and comment nodes, or an iframe document.", "Advanced", "Concept", "$('#iframe').contents().find('body');", "How is .contents() useful for iframes?"),
        ("Traversing MCQ: Which method searches down through descendant elements?", "Option B is correct. .find() searches inside descendants.", "Easy", "MCQ", "", {"A": ".filter()", "B": ".find()", "C": ".children()", "D": ".has()"}, "B", "What does .children() search?"),
        ("Traversing MCQ: Which method tests the current selected elements themselves?", "Option A is correct. .filter() filters the elements currently in the collection.", "Easy", "MCQ", "", {"A": ".filter()", "B": ".find()", "C": ".parents()", "D": ".contents()"}, "A", "What does .not() do?"),
